# cuts by ch11_ink.SP_; the middot checked in MIDDOT.md before they were typed; the rows read before marked REREAD WHOLE. Chapter 6's form.
from ch11_ink import *
S = {}
def srow(p, r, verdict, prose): S[(p, r)] = (verdict, prose)

srow(39, 1, 'MATERIAL', f'"BUT THE LAND YOU ARE CROSSING INTO TO POSSESS IS A LAND OF HILLS AND VALLEYS" (11:11) — SCRIPTURE SPEAKS IN THE LAND\'S PRAISE. SO YOU SAY; OR IN ITS SHAME, RECALLING ITS MOUNTAINS? "AND VALLEYS" — AS THE VALLEYS ARE FOR PRAISE, SO THE MOUNTAINS; AND MORE: THE MOUNTAIN\'S FRUITS ARE LIGHT, THE VALLEY\'S RICH. The head row of piska 39 ({SP_(39, 1, "בשבח", "ארץ", "ישראל", "הכתוב", "מדבר")} "Scripture speaks in the Land of Israel\'s praise"; {SP_(39, 1, "שפרות", "ההר", "קלים", "ופרות", "הבקעה", "שמנים")} "the mountain\'s fruits light and the valley\'s rich"): "mountains" read by its neighbor "valleys" — I12 (the context decides — checked); the English supplies the mountains\' shame ("upon which foreign cults were served" — a bracket, marked). The ink: "a land of hills and valleys" one seat, 8:7\'s "in the valley and in the hill" the kin (computed). Fresh in both files.')
srow(39, 2, 'MATERIAL', f'R. SHIMON BEN YOHAI: A VALLEY FIELD SOWS ONE KOR; A MOUNTAIN SOWS A KOR ON THE NORTH, A KOR ON THE SOUTH, THE EAST, THE WEST AND THE TOP — FIVE-FOLD. "THIS IS JERUSALEM, I HAVE SET HER IN THE MIDST OF THE NATIONS, AND LANDS AROUND HER" (EZEKIEL 5:5), AND ELSEWHERE HE CALLS IT "LAND" — HOW DO THE TWO VERSES STAND? A LAND WITH MANY KINDS OF LANDS IN IT: THE HOUSE OF EARTH, THE HOUSE OF SAND, THE HOUSE OF DUST. The five kors ({SP_(39, 2, "ונמצא", "חמשה", "מכפלות")} "and it comes out five-fold"; {SP_(39, 2, "כיצד", "יתקימו", "שני", "כתובים", "הללו")} "how do these two verses stand"): I13 (two verses reconciled — checked); the five a datum (the mountain\'s yield against the valley\'s). Fresh.')
srow(39, 3, 'MATERIAL', f'ANOTHER WORD: "A LAND OF HILLS AND VALLEYS" — THE TASTE OF THE MOUNTAIN\'S FRUIT IS NOT THE VALLEY\'S NOR THE VALLEY\'S THE MOUNTAIN\'S; AND THAT THIS MOUNTAIN\'S FRUIT IS NOT THAT MOUNTAIN\'S, THIS VALLEY\'S NOT THAT VALLEY\'S? "HILLS" — MANY HILLS; "VALLEYS" — MANY VALLEYS. The plurals read for their many ({SP_(39, 3, "הרים", "הרים", "הרבה")} "hills — many hills"): the registry\'s rule that a plural is at least two, read here to "many" (no code typed — the row\'s own words). Fresh.')
srow(39, 4, 'MATERIAL', f'R. SHIMON BEN YOHAI: TWELVE LANDS WERE GIVEN, AGAINST THE TWELVE TRIBES OF ISRAEL, AND NO TRIBE\'S FRUIT TASTES LIKE ANOTHER\'S — "FOR THE LAND YOU ARE ENTERING" (11:10), "AND THE LAND YOU ARE CROSSING INTO", "A LAND OF HILLS AND VALLEYS" (11:11), "A LAND WHICH THE LORD YOUR GOD SEEKS" (11:12), "TO A GOOD LAND", "A LAND OF BROOKS OF WATER" (8:7), "A LAND OF WHEAT AND BARLEY", "A LAND OF OLIVE OIL AND HONEY" (8:8), "A LAND WHERE NOT IN POVERTY", "A LAND WHOSE STONES ARE IRON" (8:9), "THE GOOD LAND WHICH HE GAVE YOU" (8:10), "A LAND FLOWING WITH MILK AND HONEY" (11:9) — TWELVE. THE TWELVE LANDS ({SP_(39, 4, "שתים", "עשרה", "ארצות", "נתנו")} "twelve lands were given"; {SP_(39, 4, "כנגד", "שנים", "עשר", "שבטי", "ישראל")} "against the twelve tribes of Israel"): E10 (the repeated expression counted — checked; chapter 8\'s ledger typed the same code on this row) — the count a token census the compile can verify (the twelve "land"s named across 8:7-10 and 11:9-12, the shelf skipping 11:10\'s "like the land of Egypt"); the Hebrew cites the twelve by the range "(דברים ו י-יא)" and "(דברים ח ז-י)" — the range forms invisible to the regex (chapter 8\'s lesson; the English\'s thirteen citations of chapters 8 and 11 asserted). Read before at chapter 8 (on 8:7-10), REREAD WHOLE here.')
srow(39, 5, 'MATERIAL', f'R. YOSE BEN MESHULLAM: AS HE SET FLAVORS IN THE LAND SO IN THE SEA — "THE GATHERING OF WATERS HE CALLED SEAS" (GENESIS 1:10): IS THERE NOT ONE SEA, "LET THE WATERS GATHER TO ONE PLACE" (1:9)? "SEAS" — THE FISH THAT COMES UP AT ACCO DOES NOT TASTE LIKE THE FISH OF SIDON, NOR SIDON\'S LIKE PANEAS\'. The seas ({SP_(39, 5, "שלא", "שוה", "טעם", "דג", "העולה", "מעכו")} "that the taste of the fish that comes up from Acco is not equal"): the plural "seas" read against the one sea (the plural rule, no code); the Mishnah\'s Mikvaot 5:4 and Parah 8:8 in the English\'s note. Read before at two Genesis sittings (gen_03 the double build, gen_26), REREAD WHOLE here.')
srow(39, 6, 'MATERIAL', f'SINCE THE MOUNTAIN\'S SOIL IS LIGHT AND THE VALLEY\'S RICH, MIGHT THE WATERS WASH THE SOIL DOWN TO THE VALLEY AND LEAVE THE VALLEY SHORT OF WATER? "A LAND OF HILLS AND VALLEYS" — THE HILL AS IT IS, THE VALLEY AS IT IS; "ASK OF THE LORD RAIN IN THE TIME OF THE LATE RAIN" (ZECHARIAH 10:1). The soil\'s balance ({SP_(39, 6, "הר", "לפי", "מה", "שהוא", "ובקעה")} "the hill as it is, and the valley"): THE ENGLISH\'S ROW 6 CARRIES THE WHOLE CASCADE 39:6-10 (the exposed, the irrigation water, the snow, the dew) which its rows 7-10 repeat — and its row 3 of piska 37 carries this row\'s opening (asserted on both files; chapter 8\'s lesson, the two files\' division). Read before at chapter 8, REREAD WHOLE here.')
srow(39, 7, 'MATERIAL', f'OR, SINCE THE LAND OF ISRAEL IS FOLDED IN MOUNTAINS, THE EXPOSED DRINKS AND THE UNEXPOSED NOT? "BY THE RAIN OF HEAVEN IT DRINKS WATER" — EXPOSED AND UNEXPOSED DRINK; "HE LOADS THE CLOUD WITH WATER" (JOB 37:11), "IT TURNS ABOUT BY HIS COUNSEL" (37:12) — THE CLOUDS SURROUND IT AND WATER IT FROM EVERY SIDE. The rain from every side ({SP_(39, 7, "גלוי", "ושאין", "גלוי", "שותה")} "exposed and unexposed drink"): 11:11\'s clause the cascade\'s first proof (the clause\'s one seat — computed). Fresh.')
srow(39, 8, 'MATERIAL', f'OR, IT DRINKS RAIN WATER BUT NOT CHANNEL WATER? "IT DRINKS WATER" — WHEN IT SAYS "WATER", CHANNEL WATER TOO; "TO A GOOD LAND, A LAND OF BROOKS OF WATER" (8:7). The second water ({SP_(39, 8, "אף", "מי", "שלוחים", "שותה")} "channel water too it drinks"): E10 (the word "water" read beyond the rain — checked; chapter 8 typed the same code on this row); 8:7 cited by name in both files. Read before at chapter 8, REREAD WHOLE here.')
srow(39, 9, 'CONTEXT', f'OR CHANNEL WATER BUT NOT SNOW WATER? "WATER" — SNOW WATER TOO: "AS THE RAIN AND THE SNOW COME DOWN FROM HEAVEN" (ISAIAH 55:10), "TO THE SNOW HE SAYS, BE EARTH" (JOB 37:6). The third water ({SP_(39, 9, "אף", "מי", "שלגים", "שותה")} "snow water too it drinks"); E10 (checked). Fresh.')
srow(39, 10, 'CONTEXT', f'OR SNOW WATER BUT NOT DEW WATER? "WATER" — DEW WATER TOO. The fourth water ({SP_(39, 10, "אף", "מי", "טללים", "שותה")} "dew water too it drinks"); E10 (checked) — the four waters of one word. Fresh.')
srow(39, 11, 'CONTEXT', f'ANOTHER WORD: AS RAINS ARE FOR A BLESSING SO DEWS — "MAY GOD GIVE YOU OF THE DEW OF HEAVEN" (GENESIS 27:28), "MY TEACHING SHALL DROP AS THE RAIN" (32:2), "I WILL BE AS THE DEW TO ISRAEL" (HOSEA 14:6), "THE REMNANT OF JACOB AS DEW FROM THE LORD" (MICAH 5:6). The piska\'s close ({SP_(39, 11, "מה", "גשמים", "לברכה", "אף", "טללים")} "as rains for a blessing so dews"): the shelf\'s word for the rains here גשמים ("rains") — the flood\'s and Leviticus\'s noun, where the chapter\'s is מטר ("rain") (computed). Fresh.')

srow(40, 1, 'MATERIAL', f'"A LAND WHICH THE LORD YOUR GOD SEEKS" (11:12) — DOES HE SEEK IT ALONE? HE SEEKS ALL LANDS, "TO RAIN ON A LAND WITHOUT MAN, TO SATISFY THE WASTE" (JOB 38:26) — WHAT THEN? AS IT WERE HE SEEKS ONLY IT, AND FOR THE SEEKING OF IT HE SEEKS ALL LANDS WITH IT. The head row of piska 40 ({SP_(40, 1, "כביכול", "אין", "דורש", "אלא", "אותה")} "as it were He seeks only it"; {SP_(40, 1, "דורש", "כל", "הארצות", "עמה")} "seeks all the lands with it"): THE LAND FIRST, THE WORLD THROUGH IT — the compile\'s DATA (the rain\'s routing; Ta\'anit 10a\'s "the Land drinks first" the docket\'s). The ink: the participle "seeks" with God as subject the book\'s one (computed). Fresh in both files.')
srow(40, 2, 'CONTEXT', f'LIKEWISE "THE KEEPER OF ISRAEL NEITHER SLUMBERS NOR SLEEPS" (PSALM 121:4) — DOES HE KEEP ISRAEL ALONE? HE KEEPS ALL (JOB 12:10): AS IT WERE ONLY ISRAEL, AND FOR THEIR KEEPING HE KEEPS ALL WITH THEM. The second "as it were" ({SP_(40, 2, "שומר", "את", "הכל", "עמהם")} "keeps all with them"). Fresh.')
srow(40, 3, 'CONTEXT', f'LIKEWISE "MY EYES AND MY HEART SHALL BE THERE ALL THE DAYS" (1 KINGS 9:3) — BUT "THE EYES OF THE LORD RANGE OVER ALL THE EARTH" (ZECHARIAH 4:10), "IN EVERY PLACE THE EYES OF THE LORD" (PROVERBS 15:3): AS IT WERE MY EYES AND MY HEART ARE ONLY THERE. The Temple\'s eyes ({SP_(40, 3, "אין", "עיני", "ולבי", "אלא", "שם")} "My eyes and My heart are only there"): the ink — "the eyes of the LORD" six seats in the Bible, 11:12 the Torah\'s one, Zechariah 4:10 and Proverbs 15:3 among the six (computed). Fresh.')
srow(40, 4, 'CONTEXT', f'LIKEWISE "THE VOICE OF THE LORD SHAKES THE WILDERNESS, THE LORD SHAKES THE WILDERNESS OF KADESH" (PSALM 29:8) — WHAT DOES IT TEACH? THIS ONE MORE. The fourth ({SP_(40, 4, "זה", "ביותר")} "this one especially"). Fresh.')
srow(40, 5, 'MATERIAL', f'"SEEKS IT" — GIVEN FOR SEEKING: TO SEPARATE FROM IT THE DOUGH-OFFERING, THE HEAVE-OFFERING AND THE TITHES. OR OTHER LANDS TOO? "IT" — IT IS GIVEN FOR SEEKING, NOT OTHER LANDS. THE LAND-BOUND DUES ({SP_(40, 5, "נתנה", "לדרישה")} "given for seeking"; {SP_(40, 5, "להפריש", "ממנה", "חלה", "תרומה", "ומעשרות")} "to separate from it the dough-offering, the heave-offering and the tithes"): the pronoun "it" read to exclude other lands (a restriction — the registry\'s E2 lists the particles "akh, raq, min", not the pronoun: no code typed); the dues the compile\'s DATA (Numbers 15:17-21, 18:11-24 by CALL at 9b; 44:1\'s rule of the land-bound commandments the kin). Fresh.')
srow(40, 6, 'MATERIAL', f'ANOTHER WORD: "SEEKS IT" — IT WAS GIVEN AS THE REWARD OF SEEKING, FOR "YOU SHALL TEACH THEM TO YOUR CHILDREN … THAT YOUR DAYS BE MULTIPLIED" (11:19-21), AND "HE GAVE THEM THE LANDS OF NATIONS … THAT THEY KEEP HIS STATUTES" (PSALM 105:44-45). The Land for study ({SP_(40, 6, "שנתנה", "בשכר", "דרישה")} "that it was given as the reward of seeking"): the row cites the chapter\'s own 11:19-21 by the range "(דברים יא יט-כא)" ("Deuteronomy 11:19-21") — invisible to the citation regex, found by the English (chapter 8\'s lesson; asserted: 40:6 absent from the Hebrew\'s hits, present in the English\'s). Fresh.')
srow(40, 7, 'MATERIAL', f'"ALWAYS THE EYES OF THE LORD YOUR GOD ARE ON IT" — ONE VERSE SAYS SO, ANOTHER "WHO LOOKS ON THE EARTH AND IT TREMBLES" (PSALM 104:32): HOW DO THE TWO STAND? WHEN ISRAEL DOES HIS WILL, "ALWAYS THE EYES" AND THEY ARE NOT HARMED; WHEN NOT, "IT TREMBLES". FOR GOOD: THE WICKED AT THE YEAR\'S HEAD, SCANT RAIN DECREED, WHO REPENTED — TO ADD IS IMPOSSIBLE, BUT "ALWAYS HIS EYES": HE BRINGS THEM IN THEIR SEASON WITH A BLESSING ON THE LAND THAT NEEDS THEM. FOR EVIL: THE RIGHTEOUS AT THE YEAR\'S HEAD, ABUNDANT RAIN DECREED, WHO TURNED BACK — TO LESSEN IS IMPOSSIBLE, BUT "IT TREMBLES": OUT OF SEASON, WITH A CURSE, ON SEAS AND DESERTS (JOB 24:19 — THE SUMMER\'S DEEDS, NO HEAVE-OFFERING AND TITHES SEPARATED, WITHHELD THE RAINS). THE RAIN JUDGED AT THE YEAR\'S HEAD ({SP_(40, 7, "כיצד", "יתקימו", "שני", "כתובים", "הללו")} "how do these two verses stand"; {SP_(40, 7, "היו", "רשעים", "בראש", "השנה")} "they were wicked at the year\'s head"; {SP_(40, 7, "מורידם", "שלא", "בזמנם")} "He brings them down out of their season"): I13 (two verses reconciled by a condition — checked); the decree fixed at Rosh Hashanah and its season and place moved by the deeds — the compile\'s DATA (Rosh Hashanah 16a-17b, Mishnah Rosh Hashanah 1:2 the docket\'s; the Tosefta Rosh Hashanah 1:13 in the English\'s note). Fresh.')
srow(40, 8, 'MATERIAL', f'"FROM THE BEGINNING OF THE YEAR TO THE END OF THE YEAR" — FROM THE YEAR\'S BEGINNING IT IS DECREED ON IT HOW MANY RAINS, HOW MANY DEWS, HOW MUCH SUN SHINES ON IT, HOW MANY WINDS BLOW ON IT. The year\'s decree ({SP_(40, 8, "שמראשית", "השנה", "נגזרו", "עליה")} "that from the year\'s beginning are decreed on it"): THE SHELF QUOTES THE VERSE PLENE — {SP_(40, 8, "מראשית")} "from the beginning of" with the aleph, where the DB writes מרשית ("from the beginning of") without it, the spelling\'s one seat in the Bible (computed; asserted on the pointed token) — a spelling the ink does not have in the shelf\'s own quotation (chapter 10\'s lesson on 10:22, again; the Talmud\'s reading of the defective form — "a year poor at its head grows rich at its end", Rosh Hashanah 16b — the docket\'s). Fresh in both files.')
srow(40, 9, 'CONTEXT', f'ANOTHER WORD: "FROM THE BEGINNING OF THE YEAR" — I WILL BLESS YOU IN COMMERCE, IN BUILDING AND PLANTING, IN BETROTHALS AND WEDDINGS, AND IN ALL YOUR HAND\'S UNDERTAKINGS. The blessing\'s list ({SP_(40, 9, "במשא", "ומתן")} "in commerce"); the plene spelling again in the row\'s quotation. Fresh.')
srow(40, 10, 'MATERIAL', f'ANOTHER WORD: "FROM THE BEGINNING OF THE YEAR TO THE END OF THE YEAR" — IS THERE FRUIT IN THE FIELD FROM THE YEAR\'S BEGINNING TO ITS END? RATHER, THEY ARE IN MY POWER TO BLESS IN THE HOUSE AS IN THE FIELD: "THE LORD WILL COMMAND THE BLESSING IN YOUR BARNS" (28:8), HAGGAI 2:19; IN THE STORE — "BLESSED IN THE CITY" (28:3); IN THE DOUGH — "BLESSED YOUR BASKET AND YOUR KNEADING TROUGH" (28:5); IN GOING IN AND OUT (28:6); IN EATING AND SATISFACTION — "YOU SHALL EAT AND BE SATISFIED AND BLESS" (8:10); WHEN THEY GO DOWN INTO YOUR BOWELS — "I WILL REMOVE SICKNESS FROM YOUR MIDST" (EXODUS 23:25): NO WORM AND ROT IN THE FRUIT, NO WINE SOURING, NO OIL STINKING. The blessing in the house ({SP_(40, 10, "הם", "ברשותי", "לתן", "בהם", "ברכה", "בבית")} "they are in My power to put a blessing in them in the house"): a chain of inclusions by proof-texts (no particle — no code); 8:10 cited by name in both files (asserted at chapter 8, the row read there). Read before at chapter 8, REREAD WHOLE here.')
srow(40, 11, 'MATERIAL', f'OR, SINCE THE MEASURE OF GOOD EXCEEDS THE MEASURE OF RETRIBUTION, MIGHT THE CURSE NOT BE IN MY POWER IN THE HOUSE AS IN THE FIELD? "YOU BROUGHT IT HOME AND I BLEW ON IT" (HAGGAI 1:9), "THE LORD WILL SEND THE CURSE ON YOU" (28:20); IN THE STORE — "CURSED IN THE CITY" (28:16); IN THE DOUGH (28:17); IN GOING IN AND OUT (28:19); IN EATING — "YOU SHALL EAT AND NOT BE SATISFIED" (LEVITICUS 26:26); IN THE BOWELS — "YOUR SICKNESS IN YOUR MIDST" (MICAH 6:14): WORM AND ROT, WINE SOURING, OIL STINKING. The curse in the house ({SP_(40, 11, "שמדת", "טובה", "מרבה", "ממדת", "פרענות")} "that the measure of good exceeds the measure of retribution"): the mirror of 40:10 by 28:15-20\'s curses against 28:3-8\'s blessings (the chapter\'s pair ahead — 11:26-28 the case\'s two arms); the measure rule stated (the Mekhilta parallels in the English\'s note). Fresh.')
srow(40, 12, 'MATERIAL', f'R. SHIMON BEN YOHAI: THE PARABLE OF THE KING OF FLESH AND BLOOD WITH MANY CHILDREN AND SLAVES FED FROM HIS HAND, THE KEYS OF THE STORE IN HIS HAND — WHEN THEY DO HIS WILL HE OPENS THE STORE AND THEY EAT AND ARE SATISFIED; WHEN NOT HE LOCKS IT AND THEY DIE OF HUNGER. SO ISRAEL: WHEN THEY DO HIS WILL, "THE LORD WILL OPEN FOR YOU HIS GOOD TREASURE, THE HEAVENS" (28:12); WHEN NOT — "AND THE ANGER OF THE LORD BE KINDLED AGAINST YOU AND HE SHUT THE HEAVENS AND THERE BE NO RAIN" (11:17). The keys of the store ({SP_(40, 12, "משל", "למלך", "בשר", "ודם")} "a parable of a king of flesh and blood"; {SP_(40, 12, "ומפתחות", "של", "אוצר", "בידו")} "and the keys of the store in his hand"): E26 (checked) — 28:12 and 11:17 THE PAIR (the same two verses at 306:4, 306:6 and 306:9 in the Ha\'azinu parables); the row cites 11:17 by name inside piska 40 (asserted). Fresh.')
srow(40, 13, 'CONTEXT', f'R. SHIMON BEN YOHAI: A LOAF AND A ROD CAME DOWN BOUND TOGETHER FROM HEAVEN — IF YOU DO THE TORAH, THE LOAF TO EAT; IF NOT, THE ROD TO BE BEATEN WITH: "IF YOU CONSENT AND HEARKEN YOU SHALL EAT THE GOOD OF THE LAND; IF YOU REFUSE AND REBEL YOU SHALL BE EATEN BY THE SWORD" (ISAIAH 1:19-20). The loaf and the rod ({SP_(40, 13, "ככר", "ומקל", "ירדו", "כרוכים")} "a loaf and a rod came down bound"). Fresh.')
srow(40, 14, 'CONTEXT', f'R. ELAZAR OF MODI\'IN: A BOOK AND A SWORD CAME DOWN BOUND TOGETHER — IF YOU DO THE TORAH WRITTEN IN THIS, YOU ARE SAVED FROM THAT; IF NOT, YOU ARE STRUCK BY IT: "THE FLAME OF THE TURNING SWORD TO GUARD THE WAY TO THE TREE OF LIFE" (GENESIS 3:24). The book and the sword ({SP_(40, 14, "ספר", "וסיף", "ירדו", "כרוכים")} "a book and a sword came down bound"). Read before at a Genesis sitting (gen_11 — the sentences and the exile), REREAD WHOLE here.')

assert sorted(S) == [(39, r) for r in range(1, 12)] + [(40, r) for r in range(1, 15)], sorted(S)
